<script>
// Nav dropdown toggle
document.querySelectorAll('.nav-item').forEach(item => {
  const trigger = item.querySelector('.nav-trigger');
  trigger.addEventListener('click', (e) => {
    e.stopPropagation();
    const wasActive = item.classList.contains('active');
    document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('active'));
    if (!wasActive) item.classList.add('active');
  });
});
document.addEventListener('click', () => {
  document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('active'));
});
document.querySelectorAll('.mega-menu').forEach(m => {
  m.addEventListener('click', e => e.stopPropagation());
});

// Mobile menu
document.getElementById('mobileMenuBtn').addEventListener('click', () => {
  document.getElementById('mainNav').classList.toggle('mobile-open');
});

// Health topics carousel
const topicsTrack = document.getElementById('topicsTrack');
document.getElementById('topicsPrev').addEventListener('click', () => {
  topicsTrack.scrollBy({ left: -200, behavior: 'smooth' });
});
document.getElementById('topicsNext').addEventListener('click', () => {
  topicsTrack.scrollBy({ left: 200, behavior: 'smooth' });
});

// Recommended reads tabs
const tabBtns = document.querySelectorAll('.tab-btn');
const cards = document.querySelectorAll('.read-card');

tabBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    tabBtns.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const tab = btn.dataset.tab;
    cards.forEach(card => {
      const cats = card.dataset.categories.split(',');
      if (tab === 'all' || cats.includes(tab)) {
        card.style.display = '';
        card.style.animation = 'fadeInUp 0.3s ease both';
      } else {
        card.style.display = 'none';
      }
    });
  });
});

// Scroll animations
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
    }
  });
}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

document.querySelectorAll('.animate-in').forEach(el => observer.observe(el));
</script>
